BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS brain_tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS brain_identities(tenant_id uuid NOT NULL REFERENCES brain_tenants(id),subject text NOT NULL,role text NOT NULL CHECK(role IN('reader','editor','reviewer','admin','operator')),email text,display_name text,groups text[] NOT NULL DEFAULT '{}',active boolean NOT NULL DEFAULT true,last_seen_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,subject));
CREATE TABLE IF NOT EXISTS brain_connectors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),provider text NOT NULL CHECK(provider IN('confluence','notion','gdrive','slack','github','custom')),name text NOT NULL,workspace_url text NOT NULL,auth_secret_ref text NOT NULL,status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','PAUSED','ERROR')),cursor text,last_sync_at timestamptz,last_success_at timestamptz,last_error_code text,document_count integer NOT NULL DEFAULT 0,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,provider,name));
CREATE TABLE IF NOT EXISTS brain_connector_acl(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),connector_id uuid NOT NULL REFERENCES brain_connectors(id) ON DELETE CASCADE,principal_type text NOT NULL CHECK(principal_type IN('role','subject','group')),principal text NOT NULL,permission text NOT NULL CHECK(permission IN('read','admin','none')),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,connector_id,principal_type,principal));
CREATE TABLE IF NOT EXISTS brain_source_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),connector_id uuid NOT NULL REFERENCES brain_connectors(id) ON DELETE CASCADE,external_id text NOT NULL,title text NOT NULL,content text NOT NULL,source_url text NOT NULL,content_sha256 text NOT NULL,source_version text NOT NULL,source_updated_at timestamptz NOT NULL,synced_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,risk_flags text[] NOT NULL DEFAULT '{}',metadata jsonb NOT NULL DEFAULT '{}'::jsonb,UNIQUE(tenant_id,connector_id,external_id));
CREATE TABLE IF NOT EXISTS brain_document_chunks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),document_id uuid NOT NULL REFERENCES brain_source_documents(id) ON DELETE CASCADE,chunk_index integer NOT NULL,content text NOT NULL,token_estimate integer NOT NULL,search_vector tsvector GENERATED ALWAYS AS(to_tsvector('english',coalesce(content,'')))STORED,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(document_id,chunk_index));
CREATE TABLE IF NOT EXISTS brain_sync_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),connector_id uuid NOT NULL REFERENCES brain_connectors(id) ON DELETE CASCADE,idempotency_key text NOT NULL,cursor_before text,cursor_after text,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','SUCCEEDED','FAILED')),upserted integer NOT NULL DEFAULT 0,deleted integer NOT NULL DEFAULT 0,error_code text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(tenant_id,connector_id,idempotency_key));
CREATE TABLE IF NOT EXISTS brain_eval_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),question text NOT NULL,expected_external_ids text[] NOT NULL,active boolean NOT NULL DEFAULT true,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS brain_eval_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),status text NOT NULL CHECK(status IN('PASSED','FAILED')),case_count integer NOT NULL,hit_count integer NOT NULL,recall_at_5 numeric(6,5) NOT NULL,threshold numeric(6,5) NOT NULL,latency_p95_ms integer NOT NULL,recorded_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS brain_queries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),requester_subject text NOT NULL,request_key text NOT NULL,question text NOT NULL,state text NOT NULL DEFAULT 'QUEUED' CHECK(state IN('QUEUED','RUNNING','DRAFT_REVIEW','APPROVED','REJECTED','FAILED')),answer text,confidence numeric(5,4),citations jsonb,unsupported_claims jsonb,provider_model text,cost_cents integer,latency_ms integer,failure_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,requester_subject,request_key));
CREATE TABLE IF NOT EXISTS brain_query_sources(query_id uuid NOT NULL REFERENCES brain_queries(id) ON DELETE CASCADE,tenant_id uuid NOT NULL REFERENCES brain_tenants(id),chunk_id uuid NOT NULL,rank integer NOT NULL,score numeric NOT NULL,source_snapshot jsonb NOT NULL,PRIMARY KEY(query_id,chunk_id));
ALTER TABLE brain_query_sources ADD COLUMN IF NOT EXISTS source_snapshot jsonb;
UPDATE brain_query_sources qs SET source_snapshot=jsonb_build_object('sourceId',c.id,'content',c.content,'externalId',d.external_id,'title',d.title,'sourceUrl',d.source_url,'sourceVersion',d.source_version,'sourceUpdatedAt',d.source_updated_at,'syncedAt',d.synced_at)FROM brain_document_chunks c JOIN brain_source_documents d ON d.id=c.document_id WHERE qs.chunk_id=c.id AND qs.source_snapshot IS NULL;
ALTER TABLE brain_query_sources ALTER COLUMN source_snapshot SET NOT NULL;
ALTER TABLE brain_query_sources DROP CONSTRAINT IF EXISTS brain_query_sources_chunk_id_fkey;
CREATE TABLE IF NOT EXISTS brain_query_approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),query_id uuid NOT NULL UNIQUE REFERENCES brain_queries(id) ON DELETE CASCADE,decision text NOT NULL CHECK(decision IN('APPROVED','REJECTED')),note text NOT NULL,reviewer_subject text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS brain_provider_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),provider text NOT NULL CHECK(provider IN('connector','answer')),operation text NOT NULL,resource_type text NOT NULL,resource_id uuid NOT NULL,idempotency_key text NOT NULL,request_payload jsonb NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','succeeded','retryable','dead-letter')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),last_error_code text,response_metadata jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,provider,idempotency_key));
CREATE TABLE IF NOT EXISTS brain_webhook_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),connector_id uuid NOT NULL REFERENCES brain_connectors(id),delivery_id text NOT NULL,body_sha256 text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,connector_id,delivery_id));
CREATE TABLE IF NOT EXISTS brain_restore_drills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES brain_tenants(id),backup_reference text NOT NULL,status text NOT NULL CHECK(status IN('scheduled','passed','failed')),evidence_uri text,recorded_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS brain_audit_events(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES brain_tenants(id),actor_subject text NOT NULL,action text NOT NULL,resource_type text NOT NULL,resource_id uuid,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL DEFAULT now());

CREATE INDEX IF NOT EXISTS brain_documents_connector_idx ON brain_source_documents(tenant_id,connector_id,deleted_at,source_updated_at DESC);
CREATE INDEX IF NOT EXISTS brain_chunks_search_idx ON brain_document_chunks USING gin(search_vector);
CREATE INDEX IF NOT EXISTS brain_acl_lookup_idx ON brain_connector_acl(tenant_id,connector_id,principal_type,principal,permission);
CREATE INDEX IF NOT EXISTS brain_jobs_due_idx ON brain_provider_jobs(status,next_attempt_at);
CREATE INDEX IF NOT EXISTS brain_queries_actor_idx ON brain_queries(tenant_id,requester_subject,created_at DESC);
CREATE OR REPLACE FUNCTION reject_brain_audit_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'brain audit is append-only';END;$$;
DROP TRIGGER IF EXISTS brain_audit_immutable ON brain_audit_events;
CREATE TRIGGER brain_audit_immutable BEFORE UPDATE OR DELETE ON brain_audit_events FOR EACH ROW EXECUTE FUNCTION reject_brain_audit_mutation();
COMMIT;
